export function AM3352(props: ChipProps<typeof pinLabels>) {
  return (
    <chip
      {...props}
      manufacturerPartNumber="AM3352BZCZ100"
      supplierPartNumbers={{ jlcpcb: ["C468247"] }}
      pinLabels={pinLabels}
      footprint={
        <footprint>
          {Object.entries(pinLabels).map(([pin, [ball]]) => (
            <smtpad
              portHints={[pin, ball]}
              pcbX={("ABCDEFGHJKLMNPRTUV".indexOf(ball[0]) - 8.5) * 0.8}
              pcbY={(Number(ball.slice(1)) - 9.5) * 0.8}
              shape="circle"
              radius={0.2}
            />
          ))}
          <courtyardrect pcbX={0} pcbY={0} width={16} height={16} />
          <silkscreenrect pcbX={0} pcbY={0} width={15.4} height={15.4} />
          <silkscreencircle pcbX={-7.8} pcbY={-7.8} radius={0.3} />
        </footprint>
      }
    />
  )
}
